import React from "react";
import api from "../api";
import { useNavigate } from "react-router-dom";
import Modal from "react-bootstrap/Modal";
import Button from "react-bootstrap/Button";

const BecomeAuthor = () => {
  const navigate = useNavigate();

  const handleBecomeAuthor = async () => {
    try {
      await api.post(
        "/auth/become-author",
        {},
        {
          headers: { Authorization: `Bearer ${localStorage.getItem("token")}` },
        }
      );
      navigate("/my-books"); // Redirect to My Books after becoming an author
    } catch (err) {
      console.error("Error becoming an author:", err);
    }
  };

  return (
    <div>
      <h2>Become an Author</h2>
      <button onClick={handleBecomeAuthor}>Confirm</button>
    </div>
  );
};

export default BecomeAuthor;
